r_template:
local({
  df <- .active_data
  p <- ggplot2::ggplot(df, ggplot2::aes(x = {{escapeR x_var}}, y = {{escapeR y_var}})) +
    ggplot2::geom_point(color = '#6366f1', size = 2.5, alpha = 0.8) +
    ggplot2::theme_minimal(base_size = 12) +
    ggplot2::labs(
      title = paste('Scatterplot:', '{{y_var}}', 'vs', '{{x_var}}'),
      x = '{{x_var}}',
      y = '{{y_var}}'
    )
  if ({{chk_smooth}}) {
    p <- p + ggplot2::geom_smooth(method = 'lm', color = '#ef4444', fill = '#fecaca', se = TRUE)
  }
  rrad_emit_plot(p, title = paste('Scatterplot:', '{{y_var}}', 'vs', '{{x_var}}'))
})
